29: function save(){ localStorage.setItem('imposter.players',JSON.stringify(state.players));localStorage.setItem('imposter.scores',JSON.stringify(state.scores));localStorage.setItem('imposter.settings',JSON.stringify(state.settings));localStorage.setItem('imposter.packs',JSON.stringify(state.customPacks)); }
30: function esc(s){ return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
31: function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.classList.remove('show'),2100)}
32: function randomize(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
33: function allCategories(){return [...BASE_CATEGORIES,...state.customPacks.map(p=>p.name)]}
34: function wordsFor(category){const custom=state.customPacks.find(p=>p.name===category);const words=custom?custom.words:WORDS[category]||[];return Array.isArray(words)?words:words.split(',').map(word=>word.trim()).filter(Boolean)}
35: function render(){clearInterval(state.interval);if(state.phase==='setup')renderSetup();else if(state.phase==='deal')renderDeal();else if(state.phase==='clues')renderClues();else if(state.phase==='discussion')renderDiscussion();else if(state.phase==='vote')renderVote();else if(state.phase==='result')renderResult()}
36: function renderSetup(){
37:  const categories=allCategories();if(!state.settings.categories.length)state.settings.categories=['Random Mix'];
38:  app.innerHTML=`<section class="hero-line"><div><div class="eyebrow">A party game for 3–12 players</div><h1>One word.<br><em>One liar.</em></h1></div><p class="hero-copy">Everyone knows the word. Except the one person pretending they do.</p></section>
