47:  <div class="setting-group"><div class="category-head"><div class="setting-label"><span>Word categories</span></div><button class="mini-link" id="toggleAll">${categories.every(c=>state.settings.categories.includes(c))?'CLEAR':'SELECT ALL'}</button></div><div class="category-grid">${categories.map(c=>`<button class="category-chip ${state.settings.categories.includes(c)?'selected':''}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><button class="custom-pack-link" id="openPack">＋ &nbsp;Create a custom word pack</button></div>
