55:  document.querySelector('#imposterChoices').onclick=e=>{const b=e.target.closest('[data-value]');if(!b)return;state.settings.imposters=+b.dataset.value;save();render()};
56:  document.querySelector('#guessToggle').onchange=e=>{state.settings.guess=e.target.checked;save()};
57:  document.querySelector('#timerToggle').onchange=e=>{state.settings.timer=e.target.checked?(state.settings.timer||60):0;save();render()};
58:  document.querySelectorAll('[data-timer]').forEach(b=>b.onclick=()=>{state.settings.timer=+b.dataset.timer;save();render()});
59:  document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{const c=b.dataset.category;state.settings.categories=state.settings.categories.includes(c)?state.settings.categories.filter(x=>x!==c):[...state.settings.categories,c];save();render()});
60:  document.querySelector('#toggleAll').onclick=()=>{state.settings.categories=categories.every(c=>state.settings.categories.includes(c))?[]:[...categories];save();render()};
