64: function addPlayer(){const input=document.querySelector('#playerInput'),name=input.value.trim();if(!name)return;if(state.players.length>=12){toast('The room is full (12 players max).');return}if(state.players.some(n=>n.toLowerCase()===name.toLowerCase())){toast('That name is already in the room.');input.focus();return}state.players.push(name);save();render();document.querySelector('#playerInput').focus()}
65: function saveEdit(commit){const input=document.querySelector('.edit-name');if(!input)return;const idx=+input.dataset.index;const name=input.value.trim();if(commit&&name&&!state.players.some((n,i)=>i!==idx&&n.toLowerCase()===name.toLowerCase()))state.players[idx]=name;else if(commit&&name)toast('Choose a name that’s not already taken.');state.editing=-1;save();render()}
66: function openPackModal(){app.insertAdjacentHTML('beforeend',`<div class="pack-modal" id="packModal"><div class="modal-card"><h2>Make your own word pack</h2><p>Give it a name and add words separated by commas or new lines. Packs are saved on this device.</p><label for="packName">Pack name</label><input id="packName" class="text-input" maxlength="24" placeholder="Inside jokes, anyone?"><label for="packWords">Your words (at least 5)</label><textarea id="packWords" placeholder="The cabin&#10;Milo's terrible cooking&#10;That one summer"></textarea><div class="modal-actions"><button class="secondary-btn" id="cancelPack">Cancel</button><button class="primary-btn" id="savePack">Save word pack</button></div></div></div>`);
67:  document.querySelector('#cancelPack').onclick=()=>document.querySelector('#packModal').remove();document.querySelector('#packModal').onclick=e=>{if(e.target.id==='packModal')e.currentTarget.remove()};document.querySelector('#savePack').onclick=()=>{const name=document.querySelector('#packName').value.trim(),words=[...new Set(document.querySelector('#packWords').value.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean))];if(!name||words.length<5){toast('Add a name and at least 5 unique words.');return}if(allCategories().some(c=>c.toLowerCase()===name.toLowerCase())){toast('That category name is already in use.');return}state.customPacks.push({name,words});state.settings.categories.push(name);save();render();toast('Word pack saved!')}};
68: function startGame(){const v=document.querySelector('#validation');if(state.players.length<3||state.settings.imposters>=state.players.length||state.settings.imposters<1){if(v)v.textContent=state.players.length<3?'Add at least 3 players to start.':'Leave at least two non-imposters in the game.';return}if(!state.settings.categories.length){if(v)v.textContent='Pick at least one word category.';return}
69:  const pool=[...new Set(state.settings.categories.flatMap(wordsFor))];if(!pool.length){toast('That word pack is empty. Choose another category.');return}let fresh=pool.filter(w=>!state.usedWords.includes(w));if(!fresh.length){state.usedWords=[];fresh=pool}state.word=fresh[Math.floor(Math.random()*fresh.length)];state.usedWords.push(state.word);const order=randomize([...state.players]);const bad=randomize([...order]).slice(0,state.settings.imposters);state.roles=order.map(name=>({name,imposter:bad.includes(name)}));state.clues=[];state.votes={};state.voteIndex=0;state.roleIndex=0;state.revealed=false;state.roleSeen=false;state.phase='deal';render()}
70: function renderDeal(){const p=state.roles[state.roleIndex];const last=state.roleIndex===state.roles.length-1;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> SECRET ROLE</div><span class="round-tag">${state.roleIndex+1} OF ${state.players.length}</span></div><section class="panel phase-card"><div class="step-count">PRIVATE SCREEN · ONLY ${esc(p.name.toUpperCase())} SHOULD LOOK</div><h1>Pass the phone<br>to <em>${esc(p.name)}.</em></h1><p class="phase-description">Make sure everyone else is looking away. Tap below when you’re ready to see your role.</p><div class="secret-box ${state.revealed?'':'hidden'}">${state.revealed?`<div class="secret-value">${p.imposter?'IMPOSTER':esc(state.word.toUpperCase())}</div><div class="secret-role ${p.imposter?'danger':''}">${p.imposter?'BLEND IN. YOU DO NOT KNOW THE WORD.':'YOU ARE IN THE KNOW · KEEP IT SECRET'}</div>`:`<div class="secret-value" style="color:#a7aaa0">••••••••</div><div class="secret-role">YOUR ROLE IS HIDDEN</div>`}</div><p class="hold-note">${state.revealed?'Memorize it. Then tap hide before passing the phone.':'No peeking, everyone else 👀'}</p><div class="action-row">${state.revealed?`<button id="hideRole" class="secondary-btn">Hide my role</button><button id="nextRole" class="primary-btn">${last?'EVERYONE’S READY':'PASS TO NEXT PLAYER'} &nbsp;→</button>`:`<button id="revealRole" class="primary-btn">REVEAL MY ROLE &nbsp;👁</button>${state.roleSeen?`<button id="nextRole" class="secondary-btn">${last?'EVERYONE’S READY':'PASS TO NEXT PLAYER'} &nbsp;→</button>`:''}`}</div><div class="progress-dots">${state.roles.map((_,i)=>`<span class="${i<=state.roleIndex?'done':''}"></span>`).join('')}</div></section><div class="setup-footnote">KEEP YOUR SCREEN TO YOURSELF — THE WHOLE GAME DEPENDS ON IT</div></div>`;
71:  const revealButton=document.querySelector('#revealRole');if(revealButton)revealButton.onclick=()=>{state.revealed=true;state.roleSeen=true;render()};if(state.revealed)document.querySelector('#hideRole').onclick=()=>{state.revealed=false;render()};if(state.revealed||state.roleSeen)document.querySelector('#nextRole').onclick=()=>{state.revealed=false;state.roleSeen=false;if(last){state.phase='clues';state.clueIndex=0}else state.roleIndex++;render()}
72: }
73: function renderClues(){const p=state.roles[state.clueIndex];const done=state.clueIndex>=state.roles.length;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> CLUE ROUND</div><span class="round-tag">${Math.min(state.clueIndex+1,state.players.length)} OF ${state.players.length}</span></div><section class="panel clue-card"><div class="clue-top"><h2 class="settings-title">One clue. Keep it clever.</h2><span class="pill-info">NO SAYING THE WORD</span></div>${done?`<div class="center"><p class="phase-description">All clues are in. Talk it out, then cast your votes.</p><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div><button id="beginDiscussion" class="primary-btn" style="max-width:320px">${state.settings.timer?'START DISCUSSION TIMER':'GO TO VOTING'} &nbsp;→</button></div>`:`<div class="current-turn"><span class="avatar">${esc(p.name.charAt(0).toUpperCase())}</span><div><strong>${esc(p.name)}’s turn</strong><small>Pass the phone privately</small></div></div><div class="clue-entry"><input id="clueInput" class="text-input" maxlength="35" autocomplete="off" placeholder="Type a one-word clue…"><button id="submitClue" class="add-btn">Give clue →</button></div><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div>`}</section><div class="setup-footnote">HINTS, NOT DEFINITIONS. GIVE THEM SOMETHING TO DISCUSS.</div></div>`;
74:  if(done){document.querySelector('#beginDiscussion').onclick=()=>{if(state.settings.timer){state.phase='discussion';state.seconds=state.settings.timer;render();startTimer()}else{state.phase='vote';render()}}}else{const input=document.querySelector('#clueInput');document.querySelector('#submitClue').onclick=submitClue;input.onkeydown=e=>{if(e.key==='Enter')submitClue()};input.focus()}}
75: function submitClue(){const input=document.querySelector('#clueInput'),clue=input.value.trim();if(!clue){toast('Add a clue before passing the phone.');return}if(clue.toLowerCase().includes(state.word.toLowerCase())){toast('Oops — don’t give the word away!');return}state.clues.push({name:state.roles[state.clueIndex].name,clue});state.clueIndex++;render()}
76: function startTimer(){clearInterval(state.interval);state.interval=setInterval(()=>{state.seconds--;if(state.seconds<=0){clearInterval(state.interval);state.seconds=0;state.phase='vote';render();toast('Time’s up! Time to vote.');return}const el=document.querySelector('#timerValue');if(el){el.textContent=clock(state.seconds);if(state.seconds<=10)el.classList.add('urgent')}},1000)}
77: function clock(s){return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
78: function renderDiscussion(){app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> DISCUSSION</div><span class="round-tag">GET TALKING</span></div><section class="panel phase-card discussion-card"><div class="eyebrow">TIME LEFT</div><div class="timer" id="timerValue">${clock(state.seconds)}</div><p class="phase-description">Compare the clues. Who sounds like they’re bluffing? Make your case, but don’t give the word away.</p><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div><div class="action-row"><button id="endDiscussion" class="primary-btn" style="max-width:300px">WE’RE READY TO VOTE &nbsp;→</button></div></section><div class="setup-footnote">EVERYONE HAS ONE VOTE. YOU CAN’T VOTE FOR YOURSELF.</div></div>`;document.querySelector('#endDiscussion').onclick=()=>{clearInterval(state.interval);state.phase='vote';render()}}
79: function renderVote(){const voter=state.roles[state.voteIndex];const final=state.voteIndex===state.roles.length-1;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> PRIVATE VOTE</div><span class="round-tag">VOTE ${state.voteIndex+1} OF ${state.roles.length}</span></div><section class="panel phase-card"><div class="step-count">SECRET BALLOT · ONLY ${esc(voter.name.toUpperCase())} SHOULD LOOK</div><h1>${esc(voter.name)},<br>who’s the imposter?</h1><p class="phase-description">Choose one person you think is bluffing. No voting for yourself.</p><div class="vote-select">${state.roles.map((p,i)=>`<button class="vote-option ${state.selectedVote===i?'selected':''}" data-vote="${i}" ${p.name===voter.name?'disabled':''}><span class="avatar">${esc(p.name.charAt(0).toUpperCase())}</span><strong>${esc(p.name)}</strong></button>`).join('')}</div><div class="action-row"><button id="castVote" class="primary-btn" style="max-width:320px" ${state.selectedVote===null?'disabled':''}>${final?'LOCK IN & REVEAL VOTES':'SUBMIT SECRET VOTE'} &nbsp;→</button></div></section><div class="setup-footnote">YOUR VOTE IS PRIVATE UNTIL EVERYONE HAS VOTED.</div></div>`;
