/* Party management and locally stored stats */
.party-bar{display:flex;align-items:flex-end;gap:12px;padding:14px 18px;margin:0 0 20px;background:#eeece5;border:1px solid var(--line);border-radius:14px}
.party-bar>div{display:grid;gap:7px;min-width:190px;margin-right:auto}
.party-select{min-height:42px;padding:0 38px 0 12px;border:1px solid var(--line);border-radius:9px;background:var(--white);color:var(--ink);font-weight:600}
.party-bar .secondary-btn{white-space:nowrap}
.party-bar .mini-link{min-height:42px;padding:0 8px}
.party-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:22px}
.party-summary>div,.stats-metrics>div{display:grid;gap:6px;padding:16px;background:#f2f0e9;border:1px solid var(--line);border-radius:12px}
.party-summary strong,.stats-metrics strong{font:600 26px 'Space Grotesk',sans-serif;letter-spacing:-1px}
.party-summary span,.stats-metrics span{font:500 9px 'DM Mono',monospace;letter-spacing:1.15px;color:var(--muted)}
.stats-wrap{max-width:980px;margin:0 auto}
.stats-wrap .phase-head{align-items:flex-end}
.stats-wrap .phase-head h1{margin:8px 0 0;font:600 clamp(32px,4vw,46px)/1.05 'Space Grotesk',sans-serif;letter-spacing:-2px}
.stats-wrap .phase-head h1 em{font-style:normal;color:#98bd4b}
.stats-panel{padding:clamp(20px,4vw,38px)}
.stats-toolbar{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:22px}
.stats-toolbar .phase-description{margin:6px 0 0}
.stats-list{display:grid;gap:8px}
.stats-row{display:grid;grid-template-columns:32px minmax(100px,1fr) minmax(120px,auto) auto;align-items:center;gap:12px;width:100%;padding:13px 15px;text-align:left;color:var(--ink);background:var(--white);border:1px solid var(--line);border-radius:10px}
.stats-row:hover{border-color:#b4d65d;background:#fbfff2}
.stats-rank{display:grid;place-items:center;width:27px;height:27px;border-radius:50%;background:#eef1e6;color:#677b39;font:500 12px 'DM Mono',monospace}
.stats-row>strong{font-weight:600}.stats-row>span:nth-last-child(2){font-size:12px;color:var(--muted)}.stats-row>b{font:500 12px 'DM Mono',monospace;white-space:nowrap}
.stats-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:4px 0 18px}
.history-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:28px 0 10px;padding-top:20px;border-top:1px solid var(--line)}
.history-heading h3,.scoreboard h3{margin:0;font:500 10px 'DM Mono',monospace;letter-spacing:1.4px}
.history-heading>span{font:10px 'DM Mono',monospace;letter-spacing:1px;color:var(--muted)}
.history-list{display:grid;gap:8px}
.history-row{display:grid;grid-template-columns:minmax(140px,1fr) auto minmax(90px,auto);align-items:center;gap:14px;padding:13px 15px;background:#f7f6f1;border:1px solid var(--line);border-radius:10px}
.history-row>div{display:grid;gap:4px}.history-row>div strong{font-weight:600}.history-row small{color:var(--muted);font-size:11px}
.history-winner{padding:6px 9px;border-radius:99px;background:#eaf3d7;color:#526b25;font:500 9px 'DM Mono',monospace;letter-spacing:.7px;white-space:nowrap}
.history-winner.imposter{background:#f9e6df;color:#a34836}
.stats-footer{display:flex;justify-content:flex-end;margin-top:22px;padding-top:16px;border-top:1px solid var(--line)}
.danger-text{color:#a34836}
#partyModal{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:20px;background:#18201999}
#partyModal .modal-card{width:min(100%,440px);padding:28px;background:var(--white);border-radius:16px;box-shadow:0 24px 80px #0003}
#partyModal h2{margin:0 0 10px;font:600 25px 'Space Grotesk',sans-serif;letter-spacing:-1px}
#partyModal p{margin:0 0 20px;color:var(--muted);line-height:1.55}
#partyModal label{display:block;margin-bottom:8px;font-size:13px;font-weight:600}
#partyModal .text-input{width:100%}
#partyModal .modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}
@media(max-width:700px){.party-bar{align-items:stretch;display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:12px}.party-bar>div{grid-column:1/-1;margin:0}.party-bar .party-stats{grid-column:1/-1}.party-bar .mini-link{justify-self:start}.party-summary{gap:7px}.party-summary>div{padding:12px 10px}.party-summary strong,.stats-metrics strong{font-size:22px}.party-summary span,.stats-metrics span{font-size:8px;letter-spacing:.6px}.stats-toolbar{align-items:flex-start;flex-direction:column}.stats-toolbar .secondary-btn{align-self:flex-end}.stats-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.stats-row{grid-template-columns:28px minmax(80px,1fr) auto;gap:8px;padding:11px}.stats-row>span:nth-last-child(2){grid-column:2;grid-row:2}.stats-row>b{grid-column:3;grid-row:1/3}.history-row{grid-template-columns:minmax(0,1fr) auto;gap:8px}.history-row>small{grid-column:1/-1}.history-winner{font-size:8px}}
@media(max-width:420px){.party-summary{grid-template-columns:1fr}.party-summary>div{grid-template-columns:auto 1fr;align-items:center}.stats-row{font-size:13px}}
EOF
