  document.querySelector('#partySelect').value=first.id;document.querySelector('#partySelect').dispatchEvent(new Event('change',{bubbles:true}));await sleep();
  assert(state.players.join(',')==='Alex,Sam,Jordan,Taylor','party switching loads isolated original players');
