  await click('#startGame');assert(state.phase==='deal','game starts');
  const secret=state.word;const imposters=state.roles.filter(p=>p.imposter).map(p=>p.name);assert(imposters.length===2,'two imposters assigned');
  while(state.phase==='deal'){
    const p=state.roles[state.roleIndex];await click('#revealRole');
    if(p.imposter){assert(document.querySelector('.secret-value').textContent==='IMPOSTER','imposter sees no secret word');assert(document.querySelector('.secret-role').textContent.includes('HINT'),'imposter gets hint');assert(!document.querySelector('.secret-role').textContent.includes(secret),'hint text excludes secret word');}
    else assert(document.querySelector('.secret-value').textContent===secret.toUpperCase(),'player sees secret word');
    await click('#nextRole');
  }
  assert(state.phase==='clues','clue phase follows role deal');
  while(state.phase==='clues'){
    if(!document.querySelector('#clueInput')){assert(state.clueIndex===state.roles.length,'all clues submitted');break}
    document.querySelector('#clueInput').value='Curious';await click('#submitClue');
  }
