  const party=state.parties.find(p=>p.id===second);
  assert(party.history.length===1,'one match recorded');assert(party.history[0].imposters.length===2,'history captures both imposters');
  assert(imposters.every(n=>state.scores[n]===2),'each imposter receives 2 points');
