input.content:
/* Verbal clue round and private category reveal */
.category-label{margin-top:17px;font:500 9px 'DM Mono',monospace;letter-spacing:1.8px;color:#92968b}
.category-value{margin-top:4px;color:#788f48;font:600 13px 'DM Mono',monospace;letter-spacing:1.2px}
.starting-player-card{max-width:680px;margin:0 auto}
.starting-player-card>.eyebrow{color:#8b9b66}
.starting-player-name{color:#252e23}
.starting-player-name em{font-style:normal;color:#98bd4b}
.verbal-instruction{max-width:440px;margin:0 auto 13px;padding:15px 18px;border:1px solid #e8eddd;border-radius:10px;background:#f7faef;color:#68715e;font-size:13px;line-height:1.6}
.verbal-instruction strong{color:#3f4e2d}
.verbal-status{margin:0 auto 20px;color:#969a91;font-size:11px}
.start-discussion-row{margin-top:21px}
.start-discussion-row .primary-btn{max-width:330px}
.starting-player-card .timer{margin:27px 0;color:#242b24}
.starting-player-card .timer.urgent{color:var(--red)}
.starting-player-card .action-row{margin-top:20px}
.starting-player-card .action-row .primary-btn{max-width:330px}
@media(max-width:650px){.verbal-instruction{padding:13px 14px}.starting-player-card .phase-description{margin-bottom:20px}}

