-:root{--paper:#f6f4ef;--ink:#1d2521;--muted:#7d827c;--line:#e4e1d9;--green:#c9f269;--green-dark:#202c18;--red:#ed6b55;--lav:#e7e1fb;--white:#fffefa;--shadow:0 12px 40px #27241a0a}*{box-sizing:border-box}html{background:var(--paper)}body{margin:0;color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh;background:radial-gradient(ellipse at 86% 9%,#f0ede4 0,transparent 28%),var(--paper)}button,input,select{font:inherit}button{cursor:pointer}.app-shell{max-width:1440px;margin:auto;padding:0 52px;min-height:100vh;display:flex;flex-direction:column}.topbar{height:88px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink);font:700 18px 'Space Grotesk',sans-serif;letter-spacing:-.7px}.brand-mark{background:var(--ink);color:var(--green);height:30px;width:30px;border-radius:9px;display:grid;place-items:center;font:700 20px 'Space Grotesk';transform:rotate(-6deg)}.brand-dot{color:var(--red)}.top-meta{font:500 10px 'DM Mono',monospace;letter-spacing:1.6px;color:#777b72;display:flex;gap:9px;align-items:center}.live-dot{height:7px;width:7px;background:#a5d850;border-radius:99px;box-shadow:0 0 0 4px #a5d85022}.icon-button{height:38px;width:38px;background:var(--white);border:1px solid var(--line);border-radius:50%;font-size:17px;color:#53584f}.icon-button.muted{opacity:.42}main{flex:1;padding:24px 0 28px}footer{height:54px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#92958c;font:10px 'DM Mono',monospace;letter-spacing:1px}.eyebrow{font:500 10px 'DM Mono',monospace;letter-spacing:1.7px;color:#8a8e83;text-transform:uppercase}.hero-line{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:28px}.hero-line h1{font:600 clamp(34px,4vw,50px)/1.03 'Space Grotesk',sans-serif;letter-spacing:-2.8px;margin:11px 0 0}.hero-line h1 em{font-style:normal;color:#98bd4b}.hero-copy